const triggerItem = $('Execute Workflow Trigger').first().json;
const question = String(triggerItem.question || '').trim();
const sessionId = triggerItem.session_id || 'hr_session_' + Date.now();
const requestId = triggerItem.request_id || require('crypto').randomUUID();
const startTime = Date.now();

const ragItems = $input.all().map(i => i.json);
const cagItem = $('Load Active CAG Snapshot').first()?.json || null;

// Filter RAG chunks by similarity >= 0.28
const validChunks = ragItems.filter(c => parseFloat(c.cosine_similarity) >= 0.28);

// Deduplicate by policy_code
const uniqueMap = new Map();
for (const chunk of validChunks) {
  if (!uniqueMap.has(chunk.policy_code)) {
    uniqueMap.set(chunk.policy_code, chunk);
  }
}
const finalChunks = Array.from(uniqueMap.values()).slice(0, 6);

let routeUsed = 'NONE';
if (finalChunks.length > 0 && cagItem) {
  routeUsed = 'CAG_RAG';
} else if (finalChunks.length > 0) {
  routeUsed = 'RAG';
} else if (cagItem) {
  routeUsed = 'CAG';
}

if (finalChunks.length === 0) {
  return [{
    json: {
      has_evidence: false,
      question,
      session_id: sessionId,
      request_id: requestId,
      start_time: startTime,
      route_used: 'NONE',
      confidence: 0.0,
      sources: [],
      prompt: '',
      fallback_answer: '**Özet Cevap:**\nBu konuda onaylı şirket İK politikası bulunamadı.\n\n> ℹ️ *Not: Bu sorgu için sistemde onaylı bir İK kuralı veya politika kaydı mevcut değildir.*'
    }
  }];
}

let contextText = '=== RESMİ İK POLİTİKA KANITLARI ===\n\n';
contextText += finalChunks.map((c, i) => `[KANIT ${i + 1}: ${c.policy_code} - ${c.title}]\nKategori: ${c.category}\nBölüm: ${c.source_section} | Sürüm: ${c.version}\nİçerik: ${c.content}`).join('\n\n---\n\n');

const systemPrompt = `Sen Yönetim Bilgi Asistanı'nın uzman İK Politika Danışmanısın.\nGörevin, yalnızca ve yalnızca sana sağlanan resmi İK politika kanıtlarını kullanarak kullanıcının sorusunu Türkçe olarak yanıtlamaktır.\n\nTEMEL KURALLAR:\n1. SADECE SAĞLANAN KANITLARI KULLAN: Kanıtlarda yer almayan hiçbir bilgiyi uydurma veya varsayma.\n2. KANIT YOKSA ASLA TAHMİN ETME: Cevap yoksa \"Bu konuda onaylı şirket İK politikası bulunamadı.\" de.\n3. ÇELİŞKİ DURUMU: En yüksek sürüm numaralı kuralı esas al ve sürüm farkını belirt.\n4. SENTETİK DEMO BİLDİRİMİ: Cevabın sonunda sentetik demo İK politikası olduğunu belirt.\n5. STANDART ÇIKTI YAPISI:\n- **Özet Cevap:** (1-2 cümlelik net doğrudan yanıt)\n- **Detaylar ve Koşullar:** (Uygulama şartları, süreler, istisnalar)\n- **Kaynak Politikalar:** (Örn: [HR-xxx] Kategori - Başlık (Bölüm x, Sürüm y))\n- > ℹ️ *Not: Bu yanıt sentetik demo İK veri seti üzerinden üretilmiştir.*`;

const fullPrompt = `${systemPrompt}\n\nAŞAĞIDAKİ RESMİ İK KANITLARINI KULLANARAK SORUYU YANITLA:\n\n${contextText}\n\nKULLANICI SORUSU: \"${question}\"\n\nCEVAP:`;

const sources = finalChunks.map(c => ({
  policy_code: c.policy_code,
  title: c.title,
  section: c.source_section || 'Genel',
  version: c.version || 1,
  effective_date: `${c.effective_from || ''} - ${c.effective_to || 'Süresiz'}`,
  similarity: parseFloat(c.cosine_similarity)
}));

return [{
  json: {
    has_evidence: true,
    question,
    session_id: sessionId,
    request_id: requestId,
    start_time: startTime,
    route_used: routeUsed,
    confidence: parseFloat(finalChunks[0].cosine_similarity),
    sources,
    prompt: fullPrompt,
    fallback_answer: ''
  }
}];

const evidence = $('Evidence Merge & Prompt Builder').first().json;

let finalAnswer = '';
if (!evidence.has_evidence) {
  finalAnswer = evidence.fallback_answer;
} else {
  const httpRes = $input.first()?.json || {};
  let raw = httpRes.response || '';
  raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  finalAnswer = raw || evidence.fallback_answer;
}

const latencyMs = Date.now() - evidence.start_time;

return [{
  json: {
    request_id: evidence.request_id,
    session_id: evidence.session_id,
    question: evidence.question,
    answer: finalAnswer,
    route_used: evidence.route_used,
    sources: evidence.sources,
    confidence: evidence.confidence,
    synthetic_notice: 'Sentetik Demo Veri',
    latency_ms: latencyMs
  }
}];
